import { test, expect } from '@playwright/test';

test.describe('Login with Invalid Password', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
  });

  test('should display error message when submitting with wrong password', async ({ page }) => {
    // Fill in the username field
    await page.locator('#username').fill('tomsmith');

    // Fill in the password field with wrong password
    await page.locator('#password').fill('wrongpassword');

    // Click the submit button
    await page.locator('button[type="submit"]').click();

    // Verify we're still on the login page
    expect(page.url()).toContain('/login');

    // Verify the error flash banner is visible
    const flashBanner = page.locator('.flash.error');
    await expect(flashBanner).toBeVisible();

    // Verify the error message contains the expected text
    await expect(flashBanner).toContainText('Your password is invalid!');
  });

  test('should keep user on login page after failed authentication attempt', async ({ page }) => {
    // Fill in credentials
    await page.locator('#username').fill('tomsmith');
    await page.locator('#password').fill('wrongpassword');

    // Submit the form
    await page.locator('button[type="submit"]').click();

    // Wait for the page to process the login attempt
    await page.waitForURL('**/login');

    // Verify the login form is still present
    const usernameField = page.locator('#username');
    const passwordField = page.locator('#password');
    const submitButton = page.locator('button[type="submit"]');

    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(submitButton).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.locator('.flash.error');
    await expect(errorMessage).toContainText('Your password is invalid!');
  });
});
